type StyleObject = Partial<CSSStyleDeclaration>;
type Pseudo = `:${string}`;
type MediaQuery = `@media ${string}`;
type CSSVariablesObject = Record<`--${string}`, string>;
type ConditionPrefix = '.' | ':' | '~' | '+' | '*' | '>' | '&.' | '&:';
type ConditionKey = `${ConditionPrefix}${string}`;
type ClassSet = Set<string>;
type SheetRootNode = HTMLElement | ShadowRoot | null;
type CreateSheetOptions = {
    rootNode?: SheetRootNode;
    nonce?: string;
};
type Styles = Partial<StyleObject & Chunks & PostConditionStyles & ShipStylesProperties>;
type PostConditionStyles = {
    [k: ConditionKey]: StyleObject | ShipStylesProperties | Chunks | PostConditionStyles;
};
type ScopedStyles<K extends string = string> = Record<S<K>, ClassSet>;
type DirectClass = string | string[];
type ShipStylesProperties = Partial<{
    '.'?: DirectClass;
    '--'?: CSSVariablesObject;
}>;
type Chunks = {
    [k: MediaQuery]: StyleObject | Record<'--', CSSVariablesObject> | PostConditionStyles;
} & {
    [k: Pseudo]: StyleObject;
};
type CreateSheetInput<K extends string> = Partial<{
    [k in K]: Styles | ShipStylesProperties;
} | PreConditions<K>>;
type PreConditions<K extends string> = {
    [k: ConditionKey]: {
        [k in K]: Styles;
    } | PreConditions<K>;
};
type S<K extends string> = Exclude<K, ConditionKey | '--' | '.' | keyof CSSStyleDeclaration | Pseudo | MediaQuery>;
type createSheetReturn = {
    create: <K extends string>(styles: CreateSheetInput<K>) => ScopedStyles<S<K>> & ScopedStyles<string>;
    keyframes: KeyframesFunction;
    getStyle: () => string;
    isApplied: () => boolean;
};
type KeyframeStages = {
    [stage: string]: StyleObject;
};
type keyframesInput<KF extends string> = Record<KF, KeyframeStages>;
type KeyframesFunction = <KF extends string>(keyframesInput: keyframesInput<KF>) => Record<KF, string>;

declare function cx(...args: unknown[]): string;

declare function createSheet(name: string, rootNode?: SheetRootNode | CreateSheetOptions): createSheetReturn;

export { type CreateSheetInput, type CreateSheetOptions, type SheetRootNode, type Styles, createSheet, cx };
